const body = $input.first().json.body || $input.first().json;
const url = (body.url || '').trim();
const lang = (body.lang || 'my').toLowerCase();
const userToken = (body.token || '').trim();
const chatId = body.chatId || '';
const geminiKey = (body.geminiKey || '').trim();
const voicePref = (body.voicePref || 'my-MM-ThihaNeural').trim();
const tonePref = (body.tonePref || 'natural').trim();
const modePref = (body.modePref === 'full') ? 'full' : 'recap';
const jobId = (body.job_id || Date.now()).toString();
const voiceMap = {
  my: { voice: voicePref, name: 'Burmese' },
  en: { voice: voicePref, name: 'English' },
  ja: { voice: voicePref, name: 'Japanese' },
  ko: { voice: voicePref, name: 'Korean' }
};

let validUrl, platform, localKey = '';

if (url.startsWith('local:')) {
  validUrl = url;
  platform = 'local';
  // Everything after "local:" is the unique upload filename key (chatId,
  // or chatId_messageId for the Telegram direct-upload path) written by
  // Upload File via SSH / Save Temp Upload - NOT just chatId, so concurrent
  // uploads from the same user don't collide on one shared filename.
  localKey = url.slice(6);
} else {
  // ASCII-only URL chars so share text like "http://xhslink.com/a/AbCd，复制本条信息..." does not swallow the trailing text into the URL.
  const urlMatch = url.match(/https?:\/\/(?:[a-z0-9-]+\.)*(?:youtube\.com|youtu\.be|tiktok\.com|xiaohongshu\.com|rednote\.com|xhslink\.com|douyin\.com|iesdouyin\.com|iqiyi\.com|iq\.com|qy\.net)(?:[\/?#][A-Za-z0-9\-._~:\/?#\[\]@!$&'()*+;=%]*)?/i);
  if (!urlMatch) {
    return [{ json: { valid: false, error: 'Invalid URL. Supported: YouTube, TikTok, Xiaohongshu/RedNote, Douyin, iQiyi, or uploaded file', chatId, geminiKey } }];
  }
  validUrl = urlMatch[0].replace(/[.,;:!?)\]]+$/, '');
  if (/youtube\.com|youtu\.be/i.test(validUrl)) platform = 'youtube';
  else if (/tiktok\.com/i.test(validUrl)) platform = 'tiktok';
  else if (/xiaohongshu\.com|rednote\.com|xhslink\.com/i.test(validUrl)) platform = 'xiaohongshu';
  else if (/douyin\.com|iesdouyin\.com/i.test(validUrl)) platform = 'douyin';
  else if (/iqiyi\.com|iq\.com|qy\.net/i.test(validUrl)) platform = 'iqiyi';
  else platform = 'unknown';
}

const voice = voiceMap[lang] || voiceMap['my'];
return [{ json: {
  valid: true, url: validUrl, platform, userToken, chatId, geminiKey, localKey,
  work_dir: '/media/dub/' + jobId,
  lang, lang_name: voice.name,
  vo_voice: voice.voice, vo_tone: tonePref, render_mode: modePref, vo_rate: '+25%', vo_pitch: '+5Hz'
}}];

const stdout = $input.first().json.stdout || '';
const stderr = $input.first().json.stderr || '';
const config = $('Validate URL').first().json;

// ── CRITICAL: Detect download failure before proceeding ──
if (stdout.includes('ERROR: source.mp4 not found') || 
    stdout.includes('Sign in to confirm you') ||
    stdout.includes('HTTP Error 403') ||
    (!stdout.includes('RESOLUTION=') && !stdout.includes('source.mp4'))) {
  const errLines = stdout.split('\n').filter(l => l.includes('ERROR')).join(' | ');
  throw new Error('Download failed: ' + (errLines || 'source.mp4 was not created. Check cookies or URL.'));
}

const resMatch = stdout.match(/RESOLUTION=(\d+)x(\d+)/);
const width  = resMatch ? parseInt(resMatch[1]) : 1080;
const height = resMatch ? parseInt(resMatch[2]) : 1920;
const durMatch = stdout.match(/DURATION=([\d.]+)/);
const duration = durMatch ? parseFloat(durMatch[1]) : 60;

// Blur zone by aspect ratio
const ar = width / height;
let blurH;
if (ar < 0.7)      blurH = Math.round(height * 0.22);
else if (ar > 1.2) blurH = Math.round(height * 0.18);
else               blurH = Math.round(height * 0.20);
const blurY = height - blurH;

return [{ json: {
  work_dir: config.work_dir,
  youtube_url: config.youtube_url,
  vo_voice: config.vo_voice,
  vo_rate: config.vo_rate,
  vo_pitch: config.vo_pitch,
  width, height, duration,
  blur_y: blurY, blur_h: blurH
}}];

// === Parse Transcript (v4 — speech segments + silent-gap slots for visual
// narration, now also splitting on LARGE SILENCES INSIDE a single Whisper
// segment) ===
// Parses Whisper SRT output into per-segment timing array, AND computes
// "gap" windows (silent/no-dialogue stretches) so those portions of the
// video can also get narration (via an attached frame + Gemini vision),
// instead of only narrating wherever original speech existed.

const stdout = $input.first().json.stdout || '';

const startMarker = '=== TRANSCRIPT_START ===';
const endMarker = '=== TRANSCRIPT_END ===';
const startIdx = stdout.indexOf(startMarker);
const endIdx = stdout.indexOf(endMarker);

let srtRaw = '';
if (startIdx !== -1 && endIdx !== -1) {
  srtRaw = stdout.substring(startIdx + startMarker.length, endIdx).trim();
}

if (!srtRaw || srtRaw.length < 5) {
  const detected = stdout.match(/Detected language: (\w+)/);
  const lang = detected ? detected[1] : 'unknown';
  throw new Error(
    'ဘီဒီယိုထဲမှာ စကားပြောသံ မတွဲ့ရပါ (Detected: ' + lang + ')။ ' +
    'စကားပြောပါတဲ့ ဘီဒီယို ထပ်ပို့ကြည့်ပါတယ်။'
  );
}

// ── Parse SRT into segments ──
function srtTimeToSec(ts) {
  // "00:01:23,456" -> 83.456
  const m = ts.match(/(\d{2}):(\d{2}):(\d{2})[,.](\d{3})/);
  if (!m) return 0;
  return parseInt(m[1])*3600 + parseInt(m[2])*60 + parseInt(m[3]) + parseInt(m[4])/1000;
}

const blocks = srtRaw.split(/\r?\n\r?\n/).map(b => b.trim()).filter(Boolean);
let rawSegments = [];

for (const block of blocks) {
  const lines = block.split(/\r?\n/);
  if (lines.length < 2) continue;
  const timing = lines.find(l => l.includes('-->'));
  if (!timing) continue;
  const tm = timing.match(/(\d{2}:\d{2}:\d{2}[,.]\d{3})\s*-->\s*(\d{2}:\d{2}:\d{2}[,.]\d{3})/);
  if (!tm) continue;
  const textLines = lines.slice(lines.indexOf(timing) + 1).join(' ').trim();
  if (!textLines) continue;
  const start_sec = srtTimeToSec(tm[1]);
  const end_sec = srtTimeToSec(tm[2]);
  rawSegments.push({
    start: tm[1], end: tm[2], start_sec, end_sec,
    duration_sec: Math.max(0.1, end_sec - start_sec),
    text: textLines, isGap: false
  });
}

if (rawSegments.length === 0) {
  const cleaned = srtRaw
    .replace(/\d{2}:\d{2}:\d{2}[,.]\d{3}\s*-->\s*\d{2}:\d{2}:\d{2}[,.]\d{3}/g, '')
    .replace(/^\d+\s*$/gm, '')
    .replace(/\n+/g, ' ')
    .replace(/\s{2,}/g, ' ')
    .trim();
  return [{ json: {
    transcript: cleaned, transcript_lines: cleaned.split('\n').length,
    segments: [], segment_count: 0, has_timing: false,
    total_speech_duration: 0, numbered_for_gemini: '', gapWindows: []
  } }];
}

// ── Parse word-level timing (forced alignment) BEFORE gap detection, so we
//    can split a Whisper segment that silently swallowed a long stretch of
//    action (Whisper often merges two separate bursts of speech, minutes
//    apart, into one "segment" whenever it doesn't detect a clean break -
//    e.g. a single stray word 25+ seconds after the rest). Left unfixed,
//    that whole silent stretch (often exactly where something IMPORTANT
//    but wordless happens - an injury, a fall, a scene transition) is
//    invisible to gap detection below, since gap detection only looks
//    BETWEEN Whisper segments, never inside one. ──
let wordsBySegIdx = {};
try {
  const ws = stdout.indexOf('=== WORDS_JSON_START ===');
  const we = stdout.indexOf('=== WORDS_JSON_END ===');
  if (ws !== -1 && we !== -1) {
    const wjson = stdout.substring(ws + '=== WORDS_JSON_START ==='.length, we).trim();
    const warr = JSON.parse(wjson);
    // warr is indexed by the ORIGINAL speech-only order (seg_idx = 1..rawSegments.length)
    for (const item of warr) {
      wordsBySegIdx[item.seg_idx] = item.words || [];
    }
  }
} catch (e) {
  wordsBySegIdx = {};
}

// ── Split any rawSegment that has a large internal silence between two
//    consecutive words into multiple pieces, exposing that silence to the
//    normal between-segment gap detection below. ──
const INTERNAL_GAP_MIN = 2.5; // seconds of silence between words, within one Whisper segment, to treat as a real break rather than a natural speech pause
function splitSegmentByWordGaps(seg, words) {
  if (!words || words.length < 2) return [seg];
  const breakIdxs = [];
  for (let i = 1; i < words.length; i++) {
    if (words[i].start - words[i - 1].end >= INTERNAL_GAP_MIN) breakIdxs.push(i);
  }
  if (breakIdxs.length === 0) return [seg];
  const pieces = [];
  let wordStart = 0;
  const boundaries = [...breakIdxs, words.length];
  for (const b of boundaries) {
    const chunk = words.slice(wordStart, b);
    if (chunk.length) {
      const s = chunk[0].start, e = chunk[chunk.length - 1].end;
      pieces.push({
        start: null, end: null, start_sec: s, end_sec: e,
        duration_sec: Math.max(0.1, e - s),
        text: chunk.map(w => w.word).join('').replace(/\s+/g, ' ').trim(),
        isGap: false, words: chunk
      });
    }
    wordStart = b;
  }
  return pieces.length ? pieces : [seg];
}

const splitRawSegments = [];
for (let i = 0; i < rawSegments.length; i++) {
  const seg = rawSegments[i];
  const words = wordsBySegIdx[i + 1] || null;
  const pieces = splitSegmentByWordGaps(seg, words);
  for (const p of pieces) splitRawSegments.push(p);
}
rawSegments = splitRawSegments;

const plainTextParts = rawSegments.map(s => s.text);
const flatTranscript = plainTextParts.join(' ');
const totalSpeech = rawSegments.reduce((s, x) => s + x.duration_sec, 0);

// ── Total video duration (for the "after last speech" gap) ──
let totalDur = rawSegments[rawSegments.length - 1].end_sec + 2.0;
const durM = stdout.match(/ORIG_DURATION=([\d.]+)s/);
if (durM) {
  const d = parseFloat(durM[1]);
  if (d > totalDur) totalDur = d;
}

// ── Compute silent GAP windows (no detected speech) worth narrating.
//    Because rawSegments has now been split on internal silences too, this
//    same between-segment scan automatically catches those as well. ──
const GAP_MIN_SEC = 0.8;     // ignore only truly tiny pauses
const MAX_GAPS = 60;         // cap frame-extraction + Gemini vision cost
let gapCandidates = [];
let cursor = 0.0;
for (const s of rawSegments) {
  if (s.start_sec - cursor >= GAP_MIN_SEC) {
    gapCandidates.push({ start_sec: cursor, end_sec: s.start_sec });
  }
  cursor = Math.max(cursor, s.end_sec);
}
if (totalDur - cursor >= GAP_MIN_SEC) {
  gapCandidates.push({ start_sec: cursor, end_sec: totalDur });
}
// Keep the longest gaps first if there are more than MAX_GAPS (most visually
// significant silent stretches), then re-sort back into chronological order.
gapCandidates.sort((a, b) => (b.end_sec - b.start_sec) - (a.end_sec - a.start_sec));
gapCandidates = gapCandidates.slice(0, MAX_GAPS);
gapCandidates.sort((a, b) => a.start_sec - b.start_sec);

const gapSegments = gapCandidates.map(g => ({
  start_sec: g.start_sec, end_sec: g.end_sec,
  duration_sec: Math.max(0.1, g.end_sec - g.start_sec),
  text: '', isGap: true
}));

// ── Merge speech + gap windows into ONE chronological list, then assign
//    unified sequential IDs (1..N) so Build Gemini Prompt / Build Plan can
//    treat every slot the same way regardless of whether it has dialogue. ──
const combined = [...rawSegments, ...gapSegments].sort((a, b) => a.start_sec - b.start_sec);
const segments = combined.map((s, i) => ({
  id: i + 1,
  start: s.start || null, end: s.end || null,
  start_sec: s.start_sec, end_sec: s.end_sec,
  duration_sec: s.duration_sec, text: s.text, isGap: !!s.isGap,
  words: s.words || null
}));

const PHRASE_GAP = 0.30;
const MIN_PHRASE_LEN = 0.6;
function chunkPhrasesFromWords(words) {
  if (!words || words.length === 0) return [];
  const phrases = [];
  let cur = [words[0]];
  for (let i = 1; i < words.length; i++) {
    const prevEnd = cur[cur.length - 1].end;
    const gap = words[i].start - prevEnd;
    const curLen = prevEnd - cur[0].start;
    if (gap >= PHRASE_GAP && curLen >= MIN_PHRASE_LEN) {
      phrases.push(cur);
      cur = [words[i]];
    } else {
      cur.push(words[i]);
    }
  }
  if (cur.length) phrases.push(cur);
  return phrases.map(ws => ({
    start: ws[0].start, end: ws[ws.length - 1].end,
    text: ws.map(w => w.word).join('').replace(/\s+/g, ' ').trim(),
    word_count: ws.length
  }));
}

// Attach phrase breakdowns for every speech segment that has word-level data
// (each split piece already carries its own .words from the split step above).
for (const s of segments) {
  if (!s.isGap && s.words && s.words.length) {
    s.phrases = chunkPhrasesFromWords(s.words);
  }
}

function fmtTs(sec) {
  const h = String(Math.floor(sec/3600)).padStart(2,'0');
  const m = String(Math.floor((sec%3600)/60)).padStart(2,'0');
  const s = String(Math.floor(sec%60)).padStart(2,'0');
  const ms = String(Math.floor((sec - Math.floor(sec))*1000)).padStart(3,'0');
  return `${h}:${m}:${s},${ms}`;
}

// ── Numbered input for Gemini. Gap slots are marked [VISUAL SCENE - no
//    dialogue] and reference their OWN segment ID; Build Gemini Prompt
//    labels each attached image with the matching "Image for segment N:"
//    text part, so there is no positional counting to keep in sync. ──
const numberedLines = [];
for (const s of segments) {
  const startTs = s.start || fmtTs(s.start_sec);
  const endTs = s.end || fmtTs(s.end_sec);
  if (s.isGap) {
    // Referencing "image N" by sequential count used to break whenever a
    // frame extraction failed for some other gap (Extract Gap Frames simply
    // omits that one, silently shifting every later gap's image number by
    // one - causing an unrelated scene/frame to get narrated under this
    // segment's ID, e.g. a wrong character or wrong location). Build
    // Gemini Prompt now labels each attached image with this segment's own
    // ID directly, so there is nothing to keep in sync here.
    numberedLines.push(`${s.id}|${startTs}|${endTs}|${s.duration_sec.toFixed(2)}s|[VISUAL SCENE - no dialogue, see the image labeled "segment ${s.id}" below]`);
  } else {
    numberedLines.push(`${s.id}|${startTs}|${endTs}|${s.duration_sec.toFixed(2)}s|${s.text}`);
    if (s.phrases && s.phrases.length > 1) {
      for (let pi = 0; pi < s.phrases.length; pi++) {
        const p = s.phrases[pi];
        const pdur = (p.end - p.start).toFixed(2);
        numberedLines.push(`${s.id}.P${pi+1}|${fmtTs(p.start)}|${fmtTs(p.end)}|${pdur}s|${p.text}`);
      }
    }
  }
}
const numberedForGemini = numberedLines.join('\n');

const gapWindowsOut = segments.filter(s => s.isGap).map(s => ({ id: s.id, start_sec: s.start_sec, end_sec: s.end_sec }));
// Pre-encode this as base64 HERE, so the downstream SSH "Extract Gap Frames"
// node can read a single flat string field directly off its own input item
// ($json.gapWindows_b64) instead of re-deriving it via a cross-node
// Buffer/JSON.stringify expression inside the SSH command string, which was
// found to unreliably resolve to an empty value in that context (root cause
// of every VISUAL SCENE segment silently losing its image).
const gapWindowsB64 = Buffer.from(JSON.stringify(gapWindowsOut), 'utf-8').toString('base64');

return [{ json: {
  transcript: flatTranscript.length > 8000 ? flatTranscript.substring(0, 8000) : flatTranscript,
  transcript_lines: flatTranscript.split('\n').length,
  segments,
  segment_count: segments.length,
  has_timing: true,
  total_speech_duration: totalSpeech,
  total_duration: totalDur,
  numbered_for_gemini: numberedForGemini,
  gapWindows: gapWindowsOut,
  gapWindows_b64: gapWindowsB64,
  gap_count: gapSegments.length
} }];

// === Build FFmpeg Plan (v3 — leading silence preserve + audio tags pass-through) ===
const geminiOut = $input.first().json;
const info = $('Parse Video Info').first().json;
const parsed = $('Parse Transcript').first().json;

// ── Extract Gemini text ──
let rawText = '';
if (geminiOut.content?.parts?.[0]?.text) rawText = geminiOut.content.parts[0].text;
else if (geminiOut.candidates?.[0]?.content?.parts?.[0]?.text) rawText = geminiOut.candidates[0].content.parts[0].text;
else if (typeof geminiOut.text === 'string') rawText = geminiOut.text;
else if (geminiOut.message?.content) rawText = geminiOut.message.content;
else rawText = JSON.stringify(geminiOut);

if (geminiOut.error) {
  throw new Error('Gemini error: ' + JSON.stringify(geminiOut.error).substring(0, 300));
}

rawText = rawText.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();
rawText = rawText.replace(/[\u200B-\u200F\uFEFF\u202A-\u202E]/g, '');
rawText = rawText.replace(/(\s)\1{2,}/g, ' ');
rawText = rawText.replace(/(.)\1{3,}/g, (m, c) => c + c + c);

// ── JSON extraction with truncation recovery ──
let parsedJson = null;
let parseError = null;
try {
  const jsonMatch = rawText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    let candidate = jsonMatch[0];
    let openCount = 0, closeCount = 0, inString = false, escape = false;
    for (const ch of candidate) {
      if (escape) { escape = false; continue; }
      if (ch === '\\') { escape = true; continue; }
      if (ch === '"') inString = !inString;
      if (inString) continue;
      if (ch === '{') openCount++;
      else if (ch === '}') closeCount++;
    }
    if (inString) candidate += '"';
    let openBr = (candidate.match(/\[/g) || []).length;
    let closeBr = (candidate.match(/\]/g) || []).length;
    while (closeBr < openBr) { candidate += ']'; closeBr++; }
    while (closeCount < openCount) { candidate += '}'; closeCount++; }
    candidate = candidate.replace(/,(\s*[}\]])/g, '$1');
    parsedJson = JSON.parse(candidate);
  }
} catch (e) {
  parseError = e.message;
  parsedJson = null;
}

const sourceSegments = parsed.segments || [];
const hasTiming = parsed.has_timing && sourceSegments.length > 0;

let voSegments = [];
let seo = {};
let voiceoverFlat = '';

if (parsedJson) {
  seo = parsedJson.seo || {};
  if (Array.isArray(parsedJson.segments) && parsedJson.segments.length > 0 && hasTiming) {
    const burmeseById = {};
    for (const seg of parsedJson.segments) {
      if (seg && seg.id != null) {
        let burText = (seg.burmese || seg.translation || seg.text || '').trim();
        // Strip zero-widths and excessive whitespace per segment
        burText = burText.replace(/[\u200B-\u200F\uFEFF\u202A-\u202E]/g, '');
        burText = burText.replace(/\s{2,}/g, ' ').trim();
        if (burText) burmeseById[String(seg.id)] = burText;
      }
    }
    for (const src of sourceSegments) {
      const bur = burmeseById[String(src.id)] || '';
      voSegments.push({
        id: src.id,
        start_sec: src.start_sec,
        end_sec: src.end_sec,
        duration_sec: src.duration_sec,
        original: src.text,
        burmese: bur,
        isGap: !!src.isGap
      });
    }
  } else if (typeof parsedJson.voiceover === 'string') {
    voiceoverFlat = parsedJson.voiceover.replace(/\\n/g, ' ').replace(/\n/g, ' ').trim();
  }
}

// ── Salvage fallback ──
const validBurmeseSegments = voSegments.filter(s => s.burmese && s.burmese.length > 0);
if (validBurmeseSegments.length === 0 && hasTiming) {
  const salvageRe = /"id"\s*:\s*(\d+)[^}]*?"burmese"\s*:\s*"([^"]*)"/g;
  let m;
  const salvagedById = {};
  while ((m = salvageRe.exec(rawText)) !== null) {
    const id = m[1];
    let txt = (m[2] || '').replace(/[\u200B-\u200F\uFEFF]/g, '').replace(/\s{2,}/g, ' ').trim();
    if (txt) salvagedById[id] = txt;
  }
  if (Object.keys(salvagedById).length > 0) {
    voSegments = [];
    for (const src of sourceSegments) {
      voSegments.push({
        id: src.id,
        start_sec: src.start_sec,
        end_sec: src.end_sec,
        duration_sec: src.duration_sec,
        original: src.text,
        burmese: salvagedById[String(src.id)] || '',
        isGap: !!src.isGap
      });
    }
  }
}

// ── Compute leading silence (gap before first speech in source video) ──
let leadingSilenceMs = 0;
if (voSegments.length > 0) {
  const firstStart = voSegments[0].start_sec;
  if (firstStart > 0.1) {
    leadingSilenceMs = Math.round(firstStart * 1000);
  }
}

// ── Assemble single VO text ──
// Prefix with [break:Xms] marker if leading silence > 100ms.
// Audio tags from Gemini (e.g., [energetic], [pause]) are preserved INLINE within burmese text.
let voTextOut = '';
let totalTargetDur = 0;

if (voSegments.length > 0) {
  if (leadingSilenceMs > 100) {
    voTextOut += `[break:${leadingSilenceMs}ms] `;
  }
  // CRITICAL: emit a [break:Xms] marker between EVERY segment so the
  // downstream chunker can map exactly one chunk per source segment.
  // If gap ≤ 50ms, still emit [break:0ms] as a chunk separator (not a real pause).
  for (let i = 0; i < voSegments.length; i++) {
    const seg = voSegments[i];
    const text = (seg.burmese || '').trim();
    if (!text) continue;
    voTextOut += text;
    totalTargetDur = Math.max(totalTargetDur, seg.end_sec);
    if (i < voSegments.length - 1) {
      const gap = Math.max(0, voSegments[i+1].start_sec - seg.end_sec);
      const gapMs = gap > 0.05 ? Math.round(gap * 1000) : 0;
      voTextOut += ` [break:${gapMs}ms] `;
    }
  }
} else {
  voTextOut = voiceoverFlat;
}

if (!voTextOut || voTextOut.length < 5) {
  throw new Error(
    'Empty translation. parseError=' + parseError +
    ' | rawLen=' + rawText.length +
    ' | preview=' + rawText.substring(0, 200).replace(/\s+/g, ' ')
  );
}

// ── Outputs ──
const segmentsB64 = Buffer.from(JSON.stringify(voSegments), 'utf-8').toString('base64');
const voB64 = Buffer.from(voTextOut, 'utf-8').toString('base64');

function secToSrt(sec) {
  const h = String(Math.floor(sec/3600)).padStart(2,'0');
  const m = String(Math.floor((sec%3600)/60)).padStart(2,'0');
  const s = String(Math.floor(sec%60)).padStart(2,'0');
  const ms = String(Math.floor((sec - Math.floor(sec))*1000)).padStart(3,'0');
